import type { Metadata } from "next"; import { ArticlePage } from "@/components/article-page"; import { Definition } from "@/components/ui"; export const metadata:Metadata={title:"BMI Guide: What Body Mass Index Means",description:"An evidence-informed guide to BMI, its formula, categories, uses, and limitations."}; export default function Page(){return <ArticlePage path="/about" title="BMI Guide: a useful screen, not the whole story" description="Understand Body Mass Index, how it is calculated, and how to use it thoughtfully alongside other markers of health."><Definition><strong>Short answer:</strong> BMI compares weight with height. It is useful for screening adult population health, but it does not directly measure body fat or diagnose disease.</Definition><h2>How BMI became a common health measure</h2><p>Health services use BMI because height and weight are straightforward to measure and the relationship between BMI categories and health outcomes has been studied in large populations. It helps identify people who may benefit from a closer look at cardiometabolic health.</p><h2>Formula and categories</h2><p>Divide kilograms by metres squared, or use pounds × 703 ÷ inches squared. For adults, below 18.5 is underweight; 18.5–24.9 is healthy weight; 25–29.9 is overweight; and 30 or above is obesity. These labels describe screening ranges, not character or diagnosis.</p><h2>Use BMI alongside context</h2><p>A clinician may also ask about blood pressure, waist circumference, sleep, medications, family history, movement, nutrition, and recent changes. This broader view is especially useful for athletes, older adults, and people whose body composition differs from average.</p><h2>Where to go next</h2><p>Use our calculator for a real-time result, then bring questions to a clinician if the result is unexpected or you have symptoms. Sustainable habits—regular meals, strength and aerobic activity, restorative sleep, and supportive care—matter at every BMI.</p></ArticlePage>}
